pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(address[] memory accounts, uint256[] memory ids) public {
        vm.assume(accounts.length > 0 && ids.length > 0);
        for (uint i = 0; i < accounts.length; i++) {
            vm.assume(accounts[i] != address(0));
        }

        bool success;
        uint256[] memory result;

        try c.balanceOfBatch(accounts, ids) returns (uint256[] memory ret) {
            success = true;
            result = ret;
        } catch {
            success = false;
        }

        if (success) {
            assertTrue(result.length == ids.length);
        }
    }
}
